import pandas as pd, numpy as np
from scipy import stats
for i in [1,3,4,6,7]:
    df = pd.read_csv(eval(f"experiment_{i}_csv"))
    print(f"--- exp {i} ---")
    if 'ResidualChlorine' in df and df['WaterClarityScore'].std()>0:
        s,ic,r,p,se = stats.linregress(df['ResidualChlorine'], df['WaterClarityScore'])
        print(f"chlorine->clarity slope={s:.3f} r={r:.3f} p={p:.2e}")
    for c in df.columns:
        if c not in ('unit_id',):
            print(c, "mean=%.3f std=%.3f"%(df[c].mean(), df[c].std()))

